package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

var (
	uploadDir = "/var/app/uploads"
	sessions  = &sync.Map{}
)

func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	sessToken := r.Header.Get("X-Session-Token")
	if _, ok := sessions.Load(sessToken); !ok {
		http.Error(w, "Unauthorized", 401)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	defer file.Close()

	// Sanitize filename - remove path separators
	filename := filepath.Base(header.Filename)
	filename = strings.ReplaceAll(filename, "..", "")

	dstPath := filepath.Join(uploadDir, filename)
	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer dst.Close()
	io.Copy(dst, file)

	w.WriteHeader(200)
	fmt.Fprintf(w, "Uploaded: %s", filename)
}

func handleConvert(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	sessToken := r.Header.Get("X-Session-Token")
	if _, ok := sessions.Load(sessToken); !ok {
		http.Error(w, "Unauthorized", 401)
		return
	}

	filename := r.FormValue("filename")
	outputFmt := r.FormValue("format")

	// Validate format is one of allowed
	allowedFormats := map[string]bool{"pdf": true, "png": true, "jpg": true}
	if !allowedFormats[outputFmt] {
		http.Error(w, "Invalid format", 400)
		return
	}

	// Build conversion command
	inputPath := filepath.Join(uploadDir, filepath.Base(filename))
	outputPath := inputPath + "." + outputFmt

	// Use LibreOffice for conversion
	cmdStr := fmt.Sprintf("libreoffice --headless --convert-to %s --outdir %s %s",
		outputFmt, uploadDir, inputPath)

	cmd := exec.Command("sh", "-c", cmdStr)
	cmd.Env = append(os.Environ(), "HOME=/tmp")
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s", string(output)), 500)
		return
	}

	// Serve the converted file
	http.ServeFile(w, r, outputPath)
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	// Simplified auth for demo
	user := r.FormValue("user")
	pass := r.FormValue("pass")
	if user == "admin" && pass == os.Getenv("ADMIN_PASS") {
		token := generateToken()
		sessions.Store(token, user)
		w.Header().Set("X-Session-Token", token)
		fmt.Fprintf(w, "OK")
		return
	}
	http.Error(w, "Invalid credentials", 401)
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	http.HandleFunc("/login", handleLogin)
	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/convert", handleConvert)
	http.ListenAndServe(":8080", nil)
}
